command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="69e6cb3f961cc3dc60a1a349ec1a0714c0621c51";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual XAML baseline fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual XAML baseline"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual XAML baseline candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-xaml-before-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual XAML worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual XAML diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "network visual XAML FAST failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network visual XAML Release build failed"}
 & python -u -X utf8 .\tests\winui\test_network_visual_gui.py --configuration Release --capture before
 if($LASTEXITCODE -ne 0){throw "network visual XAML GUI failed"}
 $source=Join-Path $temp "logs\network-visual\network-visual-before.bmp"
 if(-not (Test-Path -LiteralPath $source -PathType Leaf)){throw "network visual XAML before screenshot missing"}
 $dest=Join-Path $repo "logs\remote-evidence\network-visual-before.bmp"
 Copy-Item -LiteralPath $source -Destination $dest -Force
 Write-Host "NETWORK_VISUAL_XAML_BEFORE=PASS"
 Write-Host "NETWORK_VISUAL_BEFORE_FILE=network-visual-before.bmp"
 Write-Host "NETWORK_VISUAL_PRODUCT_FEATURE_NOT_YET_CHANGED=TRUE"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
